import{_ as i,c as a,o as t,ae as n}from"./chunks/framework.BHrE6nLq.js";const g=JSON.parse('{"title":"Phase 1: Master the \\"Minimum Viable Scaling\\"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/zeroRPM/phases/phase1/index.md","filePath":"docs/zeroRPM/phases/phase1/index.md"}'),o={name:"docs/zeroRPM/phases/phase1/index.md"};function r(s,e,l,c,h,d){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="phase-1-master-the-minimum-viable-scaling" tabindex="-1">Phase 1: Master the &quot;Minimum Viable Scaling&quot; <a class="header-anchor" href="#phase-1-master-the-minimum-viable-scaling" aria-label="Permalink to &quot;Phase 1: Master the &quot;Minimum Viable Scaling&quot;&quot;">​</a></h1><blockquote><p><em>Building the foundation for a high-performance URL shortener</em></p></blockquote><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p><strong>Objective:</strong> Build a URL shortener that may seem simple but forces critical scaling decisions.</p><p><strong>Why This Matters:</strong> This project is relatable, easy to test, and full of hidden scaling challenges that prepare we for enterprise-level problems.</p><h2 id="implementation-journey" tabindex="-1">Implementation Journey <a class="header-anchor" href="#implementation-journey" aria-label="Permalink to &quot;Implementation Journey&quot;">​</a></h2><h3 id="_1-basic-version" tabindex="-1">1. Basic Version <a class="header-anchor" href="#_1-basic-version" aria-label="Permalink to &quot;1. Basic Version&quot;">​</a></h3><ul><li><strong>Stack:</strong> Node.js + Express + PostgreSQL (for short code storage)</li><li><strong>Performance Target:</strong> Handle 100 requests per second</li><li><strong>Testing Method:</strong> Artillery for load testing</li><li><strong>Key Learning:</strong> Understanding baseline performance and identifying bottlenecks</li></ul><h3 id="_2-performance-enhancement-with-caching" tabindex="-1">2. Performance Enhancement with Caching <a class="header-anchor" href="#_2-performance-enhancement-with-caching" aria-label="Permalink to &quot;2. Performance Enhancement with Caching&quot;">​</a></h3><ul><li><strong>Implementation:</strong> Redis for hot links (leveraging the 80/20 rule where 80% of traffic hits 20% of URLs)</li><li><strong>Measurement:</strong> Compare and document cache-hit ratios with and without Redis</li><li><strong>Key Learning:</strong> Quantifying the real-world impact of caching strategies</li></ul><h3 id="_3-cost-saving-optimization" tabindex="-1">3. Cost-Saving Optimization <a class="header-anchor" href="#_3-cost-saving-optimization" aria-label="Permalink to &quot;3. Cost-Saving Optimization&quot;">​</a></h3><ul><li><strong>Database Migration:</strong> Replace PostgreSQL with SQLite + LiteFS for replication</li><li><strong>Comparison Points:</strong><ul><li>Performance differences between PostgreSQL and SQLite</li><li>Cost savings analysis</li><li>Trade-offs in scalability vs. simplicity</li></ul></li><li><strong>Key Learning:</strong> Understanding when lightweight solutions can outperform traditional databases</li></ul><h2 id="expected-outcomes" tabindex="-1">Expected Outcomes <a class="header-anchor" href="#expected-outcomes" aria-label="Permalink to &quot;Expected Outcomes&quot;">​</a></h2><p>By the end of Phase 1, we will have:</p><ul><li>A functioning URL shortener with optimized performance</li><li>Empirical data on the effectiveness of caching</li><li>A cost-efficient database implementation</li><li>Hands-on experience with fundamental scaling decisions</li></ul>',15)]))}const p=i(o,[["render",r]]);export{g as __pageData,p as default};
